escenas.animacion:
const W=A.W,H=A.H,acc=A.accent,AMB='#FFB347';
A.bg('#0b1630','#050a18');
const tB=A.k('batería',0.333),tC=A.k('celular',1.333),tA=A.k('agua',2.667),tS=A.k('salada…',3.0),tV=A.k('evaporándose',3.333),tSol=A.k('sol',4.333),tD=A.k('desierto',5.0);

function cube(x,y,s,al){
  const h=s*0.87;
  ctx.save();ctx.globalAlpha*=al;
  ctx.fillStyle='#ffffff';ctx.beginPath();ctx.moveTo(x,y-s);ctx.lineTo(x+h,y-s*0.5);ctx.lineTo(x,y);ctx.lineTo(x-h,y-s*0.5);ctx.closePath();ctx.fill();
  ctx.fillStyle='#cfe0ff';ctx.beginPath();ctx.moveTo(x-h,y-s*0.5);ctx.lineTo(x,y);ctx.lineTo(x,y+s);ctx.lineTo(x-h,y+s*0.5);ctx.closePath();ctx.fill();
  ctx.fillStyle='#8fa8d8';ctx.beginPath();ctx.moveTo(x+h,y-s*0.5);ctx.lineTo(x,y);ctx.lineTo(x,y+s);ctx.lineTo(x+h,y+s*0.5);ctx.closePath();ctx.fill();
  ctx.strokeStyle='#06101f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-h,y-s*0.5);ctx.lineTo(x,y);ctx.lineTo(x+h,y-s*0.5);ctx.moveTo(x,y);ctx.lineTo(x,y+s);ctx.stroke();
  ctx.restore();
}

// ---------- DUNAS ----------
const pD=A.p(tD-0.15,0.6,'snapSettle');
if(pD>0){
  const off=(1-pD)*400;const pts=[];
  for(let i=0;i<=30;i++){const x=-20+i*(1120/30);const y=930+off+Math.sin(i*0.45)*28+Math.sin(i*0.17+1)*22;pts.push([x,y]);}
  const poly=pts.concat([[1100,1140+off],[-20,1140+off]]);
  ctx.save();ctx.beginPath();poly.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
  const g=ctx.createLinearGradient(0,900+off,0,1140+off);g.addColorStop(0,'rgba(255,179,71,0.45)');g.addColorStop(1,'rgba(255,179,71,0.05)');
  ctx.fillStyle=g;ctx.fill();ctx.restore();
  A.lib.hatch(ctx,poly,{angle:-0.5,spacing:16,width:2,color:'rgba(255,179,71,0.35)'});
  A.lib.inkPath(ctx,pts,{width:6,color:AMB,draw:A.clamp(pD*1.4)});
}

// ---------- SOL ----------
const sp=A.pop(tSol-0.1,0.5);
if(sp>0){
  const sx=830,sy=520;
  A.rings(sx,sy,tSol,{count:3,speed:260,gap:60,maxR:260,color:AMB,lw:4,alpha:0.6});
  ctx.save();ctx.translate(sx,sy);ctx.scale(sp,sp);ctx.rotate(t*0.4);
  for(let i=0;i<12;i++){const a=i*Math.PI/6;const L=130+Math.sin(t*6+i)*10;ctx.strokeStyle=AMB;ctx.lineWidth=8;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(Math.cos(a)*100,Math.sin(a)*100);ctx.lineTo(Math.cos(a)*L,Math.sin(a)*L);ctx.stroke();}
  ctx.restore();
  A.circle(sx,sy,82*sp,{fill:AMB,glow:40});
  A.circle(sx,sy,60*sp,{fill:'#FFE29A'});
}

// ---------- GOTA: parámetros ----------
const dp=A.p(1.4,0.55,'snapSettle');
const ev=A.p(tV,2.2,'glide');
const r0=130, r=r0*(1-0.42*ev);
const baseY=905;
const cx=540, cy=baseY-r - (1-dp)*60;
const dAlpha=1-0.45*ev;

// ---------- FLECHA PUNTEADA gota -> teléfono ----------
const arP=A.p(1.6,0.5,'glide');
const yA0=baseY+20, yA1=1405;
if(arP>0){
  A.line([[540,yA0],[540,A.lerp(yA0,yA1,arP)]],{stroke:acc,lw:6,alpha:0.75,dash:[16,16]});
  if(arP>0.95){
    ctx.save();ctx.fillStyle=acc;ctx.globalAlpha=0.85;ctx.beginPath();ctx.moveTo(540,yA1+14);ctx.lineTo(518,yA1-14);ctx.lineTo(562,yA1-14);ctx.closePath();ctx.fill();ctx.restore();
  }
}

// ---------- CELULAR ----------
const ps=A.pop(0.1,0.5);
const pm=A.p(tC,0.45,'whip');
const px=540,py=A.lerp(700,1550,pm),sc=A.lerp(0.9,0.41,pm)*ps;
const lvlUp=A.p(tB,0.9,'softLand'),drain=A.p(tC,0.45,'gentleIn');
const arr=[0,1,2].map(i=>tSol+0.2+i*0.22+0.45);
let refill=0,hit=0;
arr.forEach(ta=>{refill+=0.25*A.p(ta,0.25,'popOver');if(t>=ta)hit=Math.max(hit,1-A.clamp((t-ta)/0.35));});
const lvl=Math.min(1,lvlUp*(1-0.85*drain)+refill);
const glowS=A.p(tB,0.3,'softLand')*(1-A.p(tC,0.4,'softInOut'))+hit;
if(ps>0){
  ctx.save();ctx.translate(px,py);ctx.scale(sc,sc);
  A.rect(-170,-320,340,640,{r:50,fill:'#0e1d3a',stroke:'#e8f0ff',lw:8,glow:glowS*30});
  A.rect(-150,-295,300,590,{r:36,fill:'rgba(124,252,0,'+(0.04+Math.min(1,glowS)*0.1)+')'});
  A.rect(-45,-305,90,16,{r:8,fill:'#e8f0ff'});
  A.rect(-30,-168,60,24,{r:6,fill:acc});
  A.rect(-85,-145,170,300,{r:22,stroke:acc,lw:9});
  const hh=270*lvl;
  if(hh>2)A.rect(-70,140-hh,140,hh,{r:12,fill:acc,alpha:0.85,glow:20});
  ctx.fillStyle='#0b1630';ctx.globalAlpha=lvl>0.4?1:0.4;ctx.beginPath();
  ctx.moveTo(12,-80);ctx.lineTo(-38,15);ctx.lineTo(-4,15);ctx.lineTo(-16,90);ctx.lineTo(38,-10);ctx.lineTo(4,-10);ctx.closePath();ctx.fill();ctx.globalAlpha=1;
  ctx.restore();
}
const lb=A.pop(tB+0.15,0.4)*(1-A.p(tC-0.05,0.15,'softInOut'));
if(lb>0)A.label('TU BATERÍA',540,1065,{size:62,bg:acc,color:'#06101f',scale:lb,alpha:A.clamp(lb)});

// ---------- GOTA ----------
if(dp>0){
  // vapor
  if(t>tV){
    for(let i=0;i<14;i++){
      const R=A.rand(i*7+3);const s0=tV+R()*0.6;const life=1.4;
      if(t<s0)continue;const q=((t-s0)%life)/life;
      const x0=cx+(R()-0.5)*r*1.4, y0=cy-r*1.6-q*300;
      const pts=[];for(let j=0;j<6;j++)pts.push([x0+Math.sin(j*1.1+q*8+i)*14,y0-j*14]);
      A.line(pts,{stroke:'#e8f0ff',lw:5,alpha:(1-q)*0.75*A.p(tV,0.4)});
    }
  }
  const sDp=A.lerp(0.3,1,dp), rr=r*sDp;
  const tip=1.9*rr,ang=Math.acos(1/1.9),pts=[[cx,cy-tip]];
  const a0=-Math.PI/2+ang,span=2*Math.PI-2*ang;
  for(let i=0;i<=28;i++){const a=a0+span*i/28;pts.push([cx+rr*Math.cos(a),cy+rr*Math.sin(a)]);}
  ctx.save();ctx.globalAlpha=dAlpha;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
  const g=ctx.createRadialGradient(cx-rr*0.3,cy-rr*0.3,rr*0.1,cx,cy,rr*1.3);g.addColorStop(0,'rgba(124,252,0,0.45)');g.addColorStop(1,'rgba(124,252,0,0.12)');
  ctx.fillStyle=g;ctx.shadowColor=acc;ctx.shadowBlur=30;ctx.fill();ctx.restore();
  ctx.save();ctx.globalAlpha=dAlpha;
  A.lib.hatch(ctx,pts,{angle:0.8,spacing:18,width:2,color:'rgba(124,252,0,0.3)'});
  A.lib.inkPath(ctx,pts,{width:7,color:acc,closed:true,draw:A.clamp(dp*1.3)});
  ctx.strokeStyle='rgba(255,255,255,0.7)';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.arc(cx,cy,rr*0.7,Math.PI*1.1,Math.PI*1.4);ctx.stroke();
  ctx.restore();
  // cubos de sal (~30 px)
  const slots=[[-0.45,0.05],[0.1,-0.35],[0.42,0.2],[-0.1,0.45],[0.0,-0.85],[-0.35,-0.45],[0.35,-0.6]];
  for(let i=0;i<slots.length;i++){
    const cp=A.pop(1.75+i*0.12,0.4);if(cp<=0)continue;
    const sink=A.p(tV+0.15+i*0.06,1.1,'glide');
    const bx=cx+(-0.45+(i%4)*0.3)*rr, by=cy+rr*0.6-Math.floor(i/4)*24;
    const fx=cx+slots[i][0]*rr+Math.sin(t*2+i)*5*(1-sink), fy=cy+slots[i][1]*rr+Math.cos(t*1.7+i)*5*(1-sink);
    cube(A.lerp(fx,bx,sink),A.lerp(fy,by,sink),17*cp,1);
  }
  if(sp>0)A.ray([[770,580],[cx+r*0.4,cy-r*0.8]],{color:AMB,lw:6,progress:A.p(tSol+0.1,0.5,'glide')});
}

// ---------- SAL CAYENDO AL TELÉFONO ----------
for(let i=0;i<3;i++){
  const s0=tSol+0.2+i*0.22;
  const f=A.p(s0,0.45,'gentleIn');
  if(f<=0||t>s0+0.45)continue;
  cube(540+(i-1)*8,A.lerp(baseY-20,1440,f),14,1);
}

// ---------- ETIQUETAS ----------
const l1=A.pop(1.55,0.4)*(1-A.p(tV,0.2,'softInOut'));
if(l1>0)A.label('AGUA SALADA',540,1030,{size:64,bg:'#e8f0ff',color:'#06101f',scale:l1,alpha:A.clamp(l1)});
const l2=A.pop(tV+0.1,0.4)*(1-A.p(tD-0.1,0.2,'softInOut'));
if(l2>0)A.label('SE EVAPORA',540,1030,{size:64,bg:acc,color:'#06101f',scale:l2,alpha:A.clamp(l2)});
const l3=A.pop(tD,0.4);
if(l3>0)A.label('DESIERTO',540,1030,{size:68,bg:AMB,color:'#06101f',scale:l3,alpha:A.clamp(l3)});
A.flash(tD,0.25,0.25);

const W=A.W, ac=A.accent;
A.bg('#0b1a2e','#050b16');
const kS=A.k('Salar',0.667), kAt=A.k('Atacama',1.333), kSm=A.k('salmuera:',2.0), kAg=A.k('agua',2.333), kSa=A.k('sales',3.333), kLi=A.k('litio.',4.667);
const surf=600, top=630, bot=1100, L=70, R=1010;
const BLUE='#3FA9F5';
const zoom=1+0.04*A.clamp(t/A.dur);
const shake = (t>kSm && t<kSm+0.35)?6*(1-(t-kSm)/0.35):0;
A.with(()=>{
  // subsuelo
  const pG=A.p(0,0.6,'softLand');
  ctx.save(); ctx.globalAlpha=pG;
  A.rect(L-20,surf,R-L+40,bot-surf+20,{r:24,fill:'#13202f'});
  A.lib.hatch(ctx,[[L-20,surf],[R+20,surf],[R+20,bot+20],[L-20,bot+20]],{angle:0.7,spacing:24,width:1.5,color:'rgba(255,255,255,0.10)'});
  ctx.restore();
  // salmuera llenando
  const pf=A.p(kSm-0.1,0.8,'snapSettle');
  if(pf>0){
    const lvl=A.lerp(bot,top,pf);
    ctx.save();
    ctx.beginPath(); ctx.rect(L,top-30,R-L,bot-top+30); ctx.clip();
    const g=ctx.createLinearGradient(0,top,0,bot); g.addColorStop(0,'rgba(63,169,245,0.85)'); g.addColorStop(1,'rgba(20,80,160,0.9)');
    ctx.fillStyle=g; ctx.beginPath(); ctx.moveTo(L,bot);
    for(let x=L;x<=R;x+=20){ctx.lineTo(x,lvl+Math.sin(x*0.02+t*5)*10*(1-pf*0.7));}
    ctx.lineTo(R,bot); ctx.closePath(); ctx.fill();
    // corrientes de agua
    const pA=A.p(kAg,0.5,'softInOut');
    for(let j=0;j<7;j++){
      const y=top+50+j*62; if(y<lvl) continue;
      const off=((t*140+j*97)%(R-L+300))-150;
      A.line([[L+off,y],[L+off+60,y-8],[L+off+120,y],[L+off+180,y+8]],{stroke:'rgba(255,255,255,0.55)',lw:3,alpha:pA});
    }
    ctx.restore();
  }
  // granos de roca (poroso)
  const rg=A.rand(7);
  for(let i=0;i<26;i++){
    const x=L+40+rg()*(R-L-80), y=top+40+rg()*(bot-top-80), r=18+rg()*22;
    A.circle(x,y,r,{fill:'#1a2838',alpha:0.75*pG});
  }
  // sales y litio
  const rs=A.rand(21);
  for(let i=0;i<48;i++){
    const bx=L+30+rs()*(R-L-60), by=top+30+rs()*(bot-top-60), ph=rs()*6.28;
    const s=A.pop(kSa-0.25+i*0.012,0.4); if(s<=0) continue;
    const x=bx+Math.sin(t*1.5+ph)*10, y=by+Math.cos(t*1.2+ph)*6;
    const isLi=(i%6===0);
    const pl=isLi?A.p(kLi-0.25+(i/6)*0.04,0.35,'popOver'):0;
    A.with(()=>{
      if(pl>0){A.lib.glowDot(ctx,x,y,14*pl,{color:ac}); A.circle(x,y,10,{fill:ac,alpha:pl});}
      if(pl<1) A.rect(x-7,y-7,14,14,{r:2,fill:'#ffffff',alpha:1-pl});
    },{x,y,scale:s,rot:ph+t*0.8*(1-pl)});
  }
  // litio protagonista
  const hx=540, hy=870, hs=A.pop(kLi,0.45);
  if(hs>0){
    A.rings(hx,hy,kLi,{count:3,speed:260,gap:0.18,maxR:220,color:ac,lw:4});
    A.with(()=>{
      A.circle(hx,hy,46,{fill:ac,glow:40});
      A.text('Li+',hx,hy+14,{size:44,color:'#111',weight:900,align:'center'});
    },{x:hx,y:hy,scale:hs});
  }
  // costra de sal
  const pC=A.p(kS-0.35,0.6,'whip');
  if(pC>0){
    const w=(R-L+40)*pC;
    A.rect(540-w/2,surf-26,w,30,{r:8,fill:'#ece6d6'});
    A.lib.hatch(ctx,[[540-w/2,surf-26],[540+w/2,surf-26],[540+w/2,surf+4],[540-w/2,surf+4]],{angle:-0.8,spacing:14,width:1.5,color:'rgba(120,110,90,0.5)'});
  }
  // volcanes
  const pM=A.p(kS,0.8,'glide');
  if(pM>0){
    A.lib.inkPath(ctx,[[L-20,surf-26],[180,490],[290,560],[400,470],[470,540]],{width:4,color:A.pal.paleBlue||'#9cc7ff',draw:pM});
    A.lib.inkPath(ctx,[[640,545],[780,460],[880,530],[960,500],[R+20,surf-26]],{width:4,color:A.pal.paleBlue||'#9cc7ff',draw:pM});
  }
  // flecha "Bajo"
  const pB=A.p(0.05,0.55,'glide'), fB=1-A.p(kSm-0.2,0.4,'accelExit');
  if(fB>0) A.arrow(540,430,540,760,{progress:pB,color:ac,lw:10,head:30,alpha:fB});
  // etiqueta Salar de Atacama
  const sl=A.pop(kAt,0.45);
  if(sl>0) A.label('SALAR DE ATACAMA',540,445,{size:42,bg:'rgba(10,20,35,0.85)',color:'#fff',scale:sl});
},{x:540,y:860,scale:zoom,shake});
A.flash(kLi,0.25,0.25);
// leyenda inferior
const rows=[[kAg,BLUE,'AGUA',54],[kSa,'#fff','SALES',54],[kLi,ac,'LITIO',78]];
rows.forEach((r,i)=>{
  const s=A.pop(r[0],0.45); if(s<=0) return;
  const y=1420+i*115;
  A.with(()=>{
    if(i===0) A.drop(330,y-4,22,{fill:BLUE});
    else if(i===1) A.rect(310,y-20,36,36,{r:4,fill:'#fff'});
    else {A.lib.glowDot(ctx,330,y,40,{color:ac}); A.circle(330,y,26,{fill:ac});}
    A.text(r[2],400,y+r[3]*0.35,{size:r[3],color:r[1],weight:900,align:'left'});
  },{x:330,y,scale:s});
});

const acc=A.accent||'#4DD0E1';
const kB=A.k('bombea',0.333),kS=A.k('superficie',1.333),kR=A.k('reparte',2.333),kE=A.k('enormes',3.0),kP=A.k('piscinas',3.333),kV=A.k('verdes',4.333),kAm=A.k('amarillos',5.0),kVen=A.k('ven',6.0),kEsp=A.k('espacio',7.0);
const GREEN='#5BD17F',YEL='#F5D547';
const hx=c=>[parseInt(c.slice(1,3),16),parseInt(c.slice(3,5),16),parseInt(c.slice(5,7),16)];
const mix=(a,b,p)=>{const x=hx(a),y=hx(b);return '#'+[0,1,2].map(i=>Math.round(A.lerp(x[i],y[i],A.clamp(p))).toString(16).padStart(2,'0')).join('');};
A.bg('#0b1a2a','#050c14');
const z=A.p(kVen-0.2,1.3,'whip');
// estrellas al alejarse
if(z>0){A.particles(70,7,(i,r)=>{const x=r()*1080,y=420+r()*700;A.circle(x,y,1+r()*2.5,{fill:'#fff',alpha:z*(0.4+0.6*Math.abs(Math.sin(t*3+i)))});});}
// ===== FASE 1: corte transversal =====
const out=A.p(kR,0.55,'accelExit');
if(out<1){
 const dy=out*650;
 A.with(()=>{
  const soil=[[80,640+dy],[1000,640+dy],[1000,1110+dy],[80,1110+dy]];
  A.rect(80,640+dy,920,470,{fill:'#2b2116',r:18});
  A.lib.hatch(ctx,soil,{angle:-0.6,spacing:20,width:1.5,color:'rgba(255,220,170,0.14)'});
  A.line([[60,640+dy],[1020,640+dy]],{stroke:'#E8C48A',lw:5});
  // capa de salmuera
  A.rect(100,900+dy,880,170,{fill:'rgba(77,208,225,0.25)',stroke:acc,lw:3,r:40});
  A.particles(36,3,(i,r)=>{const x=130+((r()*820+t*25*(r()-0.5)*2)%820+820)%820,y=925+r()*125+Math.sin(t*2+i)*6;A.circle(x,y+dy,4+r()*4,{fill:i%4?'#ffffff':acc,alpha:0.7});});
  A.text('SALMUERA',290,1000+dy,{size:44,color:'#fff',weight:'800',align:'center',stroke:'#05121c',strokeWidth:6,alpha:A.p(0.1,0.5)});
  // tubo
  const lvl=A.lerp(1010,600,A.p(kB,kS-kB+0.15,'glide'));
  A.rect(518,600+dy,44,420,{fill:'#0d2232',stroke:'#fff',lw:3,r:6});
  A.rect(524,lvl+dy,32,1012-lvl,{fill:acc,glow:20});
  for(let i=0;i<6;i++){const by=1000-((t*260+i*70)%400);if(by>lvl+8)A.circle(540,by+dy,5,{fill:'#fff',alpha:0.8});}
  A.arrow(610,980+dy,610,700+dy,{progress:A.p(kB,0.7,'glide'),color:acc,lw:8,head:26});
  // bomba
  const pist=t>kB?Math.sin((t-kB)*12)*14:0;
  A.rect(530,520+pist+dy,20,60,{fill:'#9fb6c8'});
  A.rect(470,565+dy,140,56,{fill:'#1c3346',stroke:'#fff',lw:4,r:10});
  A.text('BOMBA',540,596+dy,{size:28,color:'#fff',weight:'800',align:'center',alpha:A.p(kB,0.4)});
  if(t>kS){A.rings(540,600+dy,kS,{count:3,color:acc,maxR:200,lw:5});}
  A.label('SUPERFICIE',820,560+dy,{size:40,bg:acc,color:'#04121c',scale:A.pop(kS)});
 },{alpha:1-out});
}
// ===== FASE 2-3: vista cenital =====
if(t>kR-0.05){
 const pg=A.p(kR,0.5,'softLand');
 const sc=A.lerp(1,0.4,z);
 const cols=[[90,350],[410,670],[730,990]],rows=[[660,790],[815,945],[970,1100]];
 A.with(()=>{
  // desierto
  if(z>0){ctx.save();ctx.globalAlpha=z;ctx.fillStyle='#4a3a26';ctx.beginPath();
   for(let a=0;a<=64;a++){const an=a/64*Math.PI*2,rr=1050+Math.sin(an*5)*90+Math.sin(an*3+1)*70;const px=540+Math.cos(an)*rr*1.05,py=880+Math.sin(an)*rr;a?ctx.lineTo(px,py):ctx.moveTo(px,py);}
   ctx.closePath();ctx.fill();ctx.restore();
   A.lib.hatch(ctx,[[-500,-200],[1580,-200],[1580,1960],[-500,1960]],{angle:0.5,spacing:40,width:3,color:'rgba(232,196,138,'+(0.15*z)+')'});}
  // tuberías
  const pp=A.p(kR+0.1,0.7,'glide');
  A.line([[540,585],[540,625]],{stroke:acc,lw:10,alpha:pg});
  A.line([[540,625],[380,625],[220,625]],{stroke:acc,lw:10,progress:pp});
  A.line([[540,625],[700,625],[860,625]],{stroke:acc,lw:10,progress:pp});
  const pv=A.p(kR+0.4,0.7,'glide');
  A.line([[380,625],[380,1100]],{stroke:acc,lw:8,progress:pv});
  A.line([[700,625],[700,1100]],{stroke:acc,lw:8,progress:pv});
