    const f = pp * (path.length - 1), i = Math.min(Math.floor(f), path.length - 2), u = f - i;
    const px = A.lerp(path[i][0], path[i + 1][0], u), py = A.lerp(path[i][1], path[i + 1][1], u);
    A.circle(px, py, 12, { fill: acc, glow: 25 });
  }
  A.with(() => {
    const bx = 530, by = 520, bw = 220, bh = 400;
    A.rect(bx, by, bw, bh, { r: 30, fill: 'rgba(10,25,55,0.9)' });
    const lv = A.p(kV, 0.7, 'softLand');
    const fh = (bh - 40) * lv;
    if (fh > 1) {
      A.rect(bx + 20, by + bh - 20 - fh, bw - 40, fh, { r: 14, fill: acc, glow: 30 });
      for (let k = 1; k < 4; k++) { const yy = by + bh - 20 - (bh - 40) * k / 4; if (yy > by + bh - 20 - fh) A.line([[bx + 24, yy], [bx + bw - 24, yy]], { stroke: '#0b1630', lw: 5 }); }
    }
    A.rect(bx, by, bw, bh, { r: 30, stroke: WHITE, lw: 6 });
    A.rect(bx + 70, by - 34, 80, 34, { r: 8, fill: WHITE });
    A.text('Li', bx + bw / 2, by + bh / 2 + 30, { size: 110, color: lv > 0.5 ? '#0b1630' : WHITE, weight: 900, align: 'center', alpha: A.p(kV + 0.2, 0.4) });
  }, { x: 640, y: 720, scale: bScale, shake: t > kB && t < kB + 0.3 ? 6 : 0 });
  if (t > kB) A.rings(640, 720, kB, { count: 3, speed: 500, gap: 70, maxR: 420, color: acc, lw: 4, alpha: 0.6 });
  // gran signo de pregunta
  const q = A.pop(kB + 0.05, 0.5);
  if (q > 0) A.with(() => {
    A.text('?', 880, 640, { size: 260, color: acc, weight: 900, align: 'center', stroke: '#0b1630', strokeWidth: 10 });
  }, { x: 880, y: 560, scale: q, rot: Math.sin(t * 3) * 0.08 });
}
A.flash(kB, 0.25, 0.35);

// ---------- CTA seguir (zona secundaria) ----------
A.follow(540, 1520, 0.1, 1.1);
A.particles(14, 7, (i, r) => {
  const a = r() * Math.PI * 2, sp = 0.4 + r() * 0.6;
  const ph = (t * sp * 0.3 + r()) % 1;
  A.circle(540 + Math.cos(a) * (180 + ph * 220), 760 + Math.sin(a) * (180 + ph * 260), 3 + r() * 3, { fill: acc, alpha: 0.35 * (1 - ph) });
});
